package org.emransm.moviebox.phone;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import org.junit.runner.RunWith;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class SubtitleCacheScenarios {
 static final String SRT="1\n00:00:00,000 --> 00:00:30,000\n\u09ac\u09be\u0982\u09b2\u09be \u4e2d\u6587 caf\u00e9\n";
 static SubtitleCache cache(){File dir=new File(InstrumentationRegistry.getInstrumentation().getTargetContext().getCacheDir(),"owned-subtitle-cache-"+UUID.randomUUID());assertTrue(dir.mkdirs());return new SubtitleCache(dir);}
 static byte[] read(File file)throws Exception{try(InputStream input=new FileInputStream(file);ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);return output.toByteArray();}}
 static byte[] bytes(String text){return text.getBytes(StandardCharsets.UTF_8);}static void write(File file,byte[] bytes)throws Exception{try(FileOutputStream out=new FileOutputStream(file)){out.write(bytes);}}
 @Test public void validUnicodeAndUtf16CaptionsPersistAndHeaderSelectsWebVtt()throws Exception{SubtitleCache cache=cache();File srt=cache.put("srt",".srt",bytes(SRT));assertTrue(srt.isFile());assertEquals(SRT,SubtitleCache.decoded(read(srt)));assertEquals(srt,cache.find("srt"));byte[] raw=SRT.getBytes(StandardCharsets.UTF_16LE),bom=new byte[raw.length+2];bom[0]=(byte)0xff;bom[1]=(byte)0xfe;System.arraycopy(raw,0,bom,2,raw.length);assertEquals(SRT,SubtitleCache.decoded(bom));assertTrue(cache.put("utf16",".srt",bom).isFile());File vtt=cache.put("vtt",".srt",bytes("WEBVTT\n\n00:00.000 --> 00:30.000\nOwned caption"));assertTrue(vtt.getName().endsWith(".vtt"));}
 @Test public void malformedNewBytesDoNotReplaceAWorkingCaption()throws Exception{SubtitleCache cache=cache();File existing=cache.put("same",".srt",bytes(SRT));long size=existing.length();for(byte[] invalid:new byte[][]{new byte[0],bytes("<html>server error</html>"),new byte[]{(byte)0xc3,0x28},new byte[SubtitleCache.MAX_FILE_BYTES+1]})try{cache.put("same",".srt",invalid);fail();}catch(IOException expected){}assertEquals(size,existing.length());assertEquals(existing,cache.find("same"));}
 @Test public void countAndLruTrimKeepActiveAndRecentlyUsedCaptions()throws Exception{SubtitleCache cache=cache();List<File> files=new ArrayList<>();for(int i=0;i<40;i++){File file=cache.put("caption-"+i,".srt",bytes(SRT));file.setLastModified(System.currentTimeMillis()-100000+i);files.add(file);}cache.protect(files.get(0));assertEquals(files.get(1),cache.find("caption-1"));cache.put("caption-40",".srt",bytes(SRT));assertTrue(files.get(0).exists());assertTrue(files.get(1).exists());assertFalse(files.get(2).exists());assertTrue(cache.directory().listFiles().length<=SubtitleCache.MAX_FILES);}
 @Test public void byteBudgetRemainsBoundedWithoutEvictingTheActiveCaption()throws Exception{SubtitleCache cache=cache();byte[] large=new byte[2*1024*1024];Arrays.fill(large,(byte)'x');byte[] cue=bytes(SRT);System.arraycopy(cue,0,large,0,cue.length);File active=cache.put("active",".srt",large);cache.protect(active);for(int i=0;i<14;i++)cache.put("large-"+i,".srt",large);long total=0;for(File file:cache.directory().listFiles())total+=file.length();assertTrue(total<=SubtitleCache.MAX_BYTES);assertTrue(active.exists());}
 @Test public void clearAndAgeTrimPreserveActiveAndUnrelatedLibraryFiles()throws Exception{SubtitleCache cache=cache();File active=cache.put("active",".srt",bytes(SRT)),old=cache.put("old",".srt",bytes(SRT));cache.protect(active);long before=System.currentTimeMillis()-SubtitleCache.MAX_AGE_MS-5000;active.setLastModified(before);old.setLastModified(before);File library=new File(cache.directory(),"library.json");write(library,bytes("private-owned-fixture"));cache.trim();assertTrue(active.exists());assertFalse(old.exists());cache.put("other",".srt",bytes(SRT));assertEquals(1,cache.clear());assertTrue(active.exists());assertTrue(library.exists());cache.protect(null);assertEquals(1,cache.clear());}
 @Test public void invalidLegacyAndAbandonedAtomicFilesAreRemovedSafely()throws Exception{SubtitleCache cache=cache();File invalid=new File(cache.directory(),Api.md5(bytes("bad"))+".srt");write(invalid,bytes("server error"));assertNull(cache.find("bad"));assertFalse(invalid.exists());File orphan=new File(cache.directory(),Api.md5(bytes("old"))+".srt.new");write(orphan,bytes("partial"));cache.trim();assertFalse(orphan.exists());}
}
